//! End-to-end extraction tests over the synthetic born-digital
//! fixtures in tests/fixtures/ (generated by
//! `cargo run -p tax-doc --example gen-fixtures`). Every expected
//! value below is the exact amount printed in the fixture.

use std::path::PathBuf;
use tax_core::TaxParams;
use tax_doc::{extract_document, extract_words, ExtractReport, ExtractStatus};
use tax_forms::{I1099DivInput, I1099IntInput, I1099NecInput, W2Input};

fn fixture(name: &str) -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("tests")
        .join("fixtures")
        .join(name)
}

fn extract(name: &str) -> ExtractReport {
    let params = TaxParams::load_2025().unwrap();
    extract_document(&fixture(name), &params).unwrap()
}

fn field<'a>(report: &'a ExtractReport, key: &str) -> Option<&'a str> {
    report.fields.get(key).and_then(|v| v.as_str())
}

/// The fixture documents print the employee/recipient SSN
/// 123-45-6789 in their SSN/TIN boxes. It must never appear anywhere
/// in an extraction report — no rule may read those boxes.
fn assert_no_ssn(report: &ExtractReport) {
    let json = serde_json::to_string(report).unwrap();
    assert!(
        !json.contains("123-45-6789"),
        "report leaks the SSN: {json}"
    );
    assert!(
        !json.contains("123456789"),
        "report leaks the SSN digits: {json}"
    );
}

/// The node payload (minus its "type" key) must deserialize into the
/// exact struct `tax form add` validates against.
fn node_as<T: serde::de::DeserializeOwned>(report: &ExtractReport) -> T {
    let mut node = report.node.clone().expect("node present");
    node.as_object_mut().unwrap().remove("type");
    serde_json::from_value(node).unwrap()
}

#[test]
fn w2_grid_two_copies_exact_values() {
    let r = extract("w2-grid.pdf");
    assert_eq!(r.form.as_deref(), Some("w2"));
    assert_eq!(r.status, ExtractStatus::Extracted);
    assert_eq!(r.method.as_deref(), Some("text"));
    assert_eq!(field(&r, "wages"), Some("5234075"));
    assert_eq!(field(&r, "federal_withholding"), Some("482550"));
    assert_eq!(field(&r, "social_security_wages"), Some("5500000"));
    assert_eq!(field(&r, "social_security_tax"), Some("341000"));
    assert_eq!(field(&r, "medicare_wages"), Some("5500000"));
    assert_eq!(field(&r, "medicare_tax"), Some("79750"));
    assert_eq!(field(&r, "employer_ein"), Some("12-3456789"));
    assert_eq!(field(&r, "employer_name"), Some("Acme Widgets Inc"));
    // The two printed copies are detected and reported, not merged.
    assert!(
        r.warnings.iter().any(|w| w.contains("multiple copies")),
        "warnings: {:?}",
        r.warnings
    );
    // Rate cross-checks pass: no warning/error findings.
    assert!(
        r.checks.iter().all(|c| c.severity == "info"),
        "checks: {:?}",
        r.checks
    );
    // Evidence carries page, printed label, raw token and box.
    let ev = &r.evidence["wages"];
    assert_eq!(ev["page"], 1);
    assert_eq!(ev["box"], "1");
    assert_eq!(ev["raw"], "52,340.75");
    assert!(ev["label"].as_str().unwrap().contains("Wages"));
    // The node round-trips into the exact payload struct.
    let w2: W2Input = node_as(&r);
    assert_eq!(w2.wages.cents(), 5_234_075);
    assert_eq!(w2.employer_ein, "12-3456789");
    assert_no_ssn(&r);
}

#[test]
fn w2_adp_style_label_left_value_right() {
    let r = extract("w2-adp.pdf");
    assert_eq!(r.status, ExtractStatus::Extracted);
    assert_eq!(field(&r, "wages"), Some("9876543"));
    assert_eq!(field(&r, "federal_withholding"), Some("1521099"));
    assert_eq!(field(&r, "social_security_wages"), Some("9876543"));
    assert_eq!(field(&r, "social_security_tax"), Some("612346"));
    assert_eq!(field(&r, "medicare_wages"), Some("9876543"));
    assert_eq!(field(&r, "medicare_tax"), Some("143210"));
    assert_eq!(field(&r, "employer_ein"), Some("47-2091853"));
    assert_eq!(field(&r, "employer_name"), Some("Globex Corporation"));
    assert!(r.checks.iter().all(|c| c.severity == "info"));
    let w2: W2Input = node_as(&r);
    assert_eq!(w2.federal_withholding.cents(), 1_521_099);
    assert_no_ssn(&r);
}

#[test]
fn w2_adp_tj_kerning_words_reassembled() {
    // The footer line is one TJ array with the word "information"
    // split mid-word by a kerning adjustment; word assembly must join
    // it back (gap below threshold) rather than splitting the word.
    let words = extract_words(&fixture("w2-adp.pdf")).unwrap();
    assert!(
        words.iter().any(|w| w.text == "information"),
        "words: {:?}",
        words.iter().map(|w| &w.text).collect::<Vec<_>>()
    );
}

#[test]
fn w2_partial_blank_required_box() {
    let r = extract("w2-partial.pdf");
    assert_eq!(r.status, ExtractStatus::Partial);
    assert_eq!(field(&r, "wages"), Some("5234075"));
    // Box 2 is required by the payload and printed blank: omitted,
    // never zero-filled.
    assert_eq!(field(&r, "federal_withholding"), None);
    // Box 6 is optional (Option field): also omitted, not zeroed.
    assert_eq!(field(&r, "medicare_tax"), None);
    assert_eq!(field(&r, "social_security_tax"), Some("341000"));
    assert!(
        r.warnings.iter().any(|w| w.contains("federal_withholding")),
        "warnings: {:?}",
        r.warnings
    );
    // Cross-checks are honestly skipped, not faked.
    assert!(r.checks.iter().any(|c| c.code == "w2_checks_skipped"));
    // The partial node must NOT validate as a W2Input.
    let mut node = r.node.clone().unwrap();
    node.as_object_mut().unwrap().remove("type");
    assert!(serde_json::from_value::<W2Input>(node).is_err());
    assert_no_ssn(&r);
}

#[test]
fn w2_acroform_fields() {
    let r = extract("w2-acroform.pdf");
    assert_eq!(r.status, ExtractStatus::Extracted);
    assert_eq!(r.method.as_deref(), Some("acroform"));
    assert_eq!(field(&r, "wages"), Some("5234075"));
    assert_eq!(field(&r, "federal_withholding"), Some("482550"));
    assert_eq!(field(&r, "social_security_wages"), Some("5500000"));
    assert_eq!(field(&r, "social_security_tax"), Some("341000"));
    assert_eq!(field(&r, "medicare_wages"), Some("5500000"));
    assert_eq!(field(&r, "medicare_tax"), Some("79750"));
    assert_eq!(field(&r, "employer_ein"), Some("12-3456789"));
    assert_eq!(field(&r, "employer_name"), Some("Acme Widgets Inc"));
    assert_eq!(r.evidence["wages"]["source"], "acroform");
    assert!(r.checks.iter().all(|c| c.severity == "info"));
    assert_no_ssn(&r);
}

#[test]
fn int_exact_values_and_empty_box_zero() {
    let r = extract("int.pdf");
    assert_eq!(r.form.as_deref(), Some("form_1099_int"));
    assert_eq!(r.node_type.as_deref(), Some("1099-int"));
    assert_eq!(r.status, ExtractStatus::Extracted);
    assert_eq!(field(&r, "interest_income"), Some("123456"));
    assert_eq!(field(&r, "tax_exempt_interest"), Some("25000"));
    // Box 4 is printed blank; the payload defaults it to zero and the
    // box was verifiably located, so it is emitted as "0" with
    // empty-box evidence — not silently dropped.
    assert_eq!(field(&r, "federal_withholding"), Some("0"));
    assert_eq!(r.evidence["federal_withholding"]["empty"], true);
    assert_eq!(field(&r, "payer_name"), Some("First Test Bank"));
    // The brief's scope: payer EIN is not extracted for 1099-INT even
    // though the fixture prints a PAYER'S TIN.
    assert_eq!(field(&r, "payer_ein"), None);
    let input: I1099IntInput = node_as(&r);
    assert_eq!(input.interest_income.cents(), 123_456);
    assert_eq!(input.payer_name, "First Test Bank");
    assert_no_ssn(&r);
}

#[test]
fn div_exact_values() {
    let r = extract("div.pdf");
    assert_eq!(r.form.as_deref(), Some("form_1099_div"));
    assert_eq!(r.status, ExtractStatus::Extracted);
    assert_eq!(field(&r, "total_ordinary_dividends"), Some("250000"));
    assert_eq!(field(&r, "qualified_dividends"), Some("210025"));
    assert_eq!(field(&r, "federal_withholding"), Some("12500"));
    assert_eq!(field(&r, "payer_name"), Some("Test Brokerage LLC"));
    assert!(
        r.checks.iter().all(|c| c.severity != "error"),
        "checks: {:?}",
        r.checks
    );
    let input: I1099DivInput = node_as(&r);
    assert_eq!(input.total_ordinary_dividends.cents(), 250_000);
    assert_eq!(input.qualified_dividends.cents(), 210_025);
    assert_no_ssn(&r);
}

#[test]
fn nec_exact_values_with_payer_ein() {
    let r = extract("nec.pdf");
    assert_eq!(r.form.as_deref(), Some("form_1099_nec"));
    assert_eq!(r.status, ExtractStatus::Extracted);
    assert_eq!(field(&r, "nonemployee_compensation"), Some("1875000"));
    assert_eq!(field(&r, "federal_withholding"), Some("0"));
    assert_eq!(r.evidence["federal_withholding"]["empty"], true);
    assert_eq!(field(&r, "payer_ein"), Some("83-2910475"));
    assert_eq!(field(&r, "payer_name"), Some("Client Co LLC"));
    let input: I1099NecInput = node_as(&r);
    assert_eq!(input.nonemployee_compensation.cents(), 1_875_000);
    assert_eq!(input.payer_ein.as_deref(), Some("83-2910475"));
    // `expenses` is not a printed box: never extracted into the node.
    assert!(r.node.as_ref().unwrap().get("expenses").is_none());
    assert_no_ssn(&r);
}

#[test]
fn image_only_needs_ocr() {
    let r = extract("image-only.pdf");
    assert_eq!(r.status, ExtractStatus::NeedsOcr);
    assert!(r.node.is_none());
    assert!(r.fields.is_empty());
    assert!(
        r.warnings.iter().any(|w| w.contains("agent-vision")),
        "warnings: {:?}",
        r.warnings
    );
}

#[test]
fn receipt_unrecognized() {
    let r = extract("receipt.pdf");
    assert_eq!(r.status, ExtractStatus::Unrecognized);
    assert_eq!(r.form, None);
    assert!(r.node.is_none());
}

#[test]
fn f1040_recognized_but_not_extractable() {
    let r = extract("f1040-title.pdf");
    assert_eq!(r.status, ExtractStatus::Unrecognized);
    assert_eq!(r.form.as_deref(), Some("f1040"));
    assert!(r.node.is_none());
}

#[test]
fn missing_file_is_an_error_not_a_guess() {
    let params = TaxParams::load_2025().unwrap();
    assert!(extract_document(&fixture("no-such.pdf"), &params).is_err());
}
